package br.com.devedores.app;
import android.app.*;import android.content.*;import android.os.Build;
public class LoanAlarmReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent in){String type=in.getStringExtra("type");String id=in.getStringExtra("id");String title=in.getStringExtra("title");NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel="vencimentos";if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(channel,"Vencimentos e lembretes",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Alertas do Devedores");ch.enableVibration(true);nm.createNotificationChannel(ch);}Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,Math.abs(id.hashCode()),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,channel):new Notification.Builder(c);b.setSmallIcon(br.com.devedores.app.R.drawable.ic_notification).setContentTitle(type.equals("loan")?"Vencimento de parcela":"Lembrete").setContentText(title==null?"Você tem um alerta no Devedores":title).setAutoCancel(true).setContentIntent(pi).setPriority(Notification.PRIORITY_HIGH);nm.notify(Math.abs(id.hashCode()),b.build());}
}
